WITH metrics AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, SUM(monthly_fee) OVER w_recent AS running_monthly_fee, STDDEV_SAMP(monthly_fee) OVER (PARTITION BY customer_id) AS customer_id_stddev_samp_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_5_prior, NTILE(4) OVER (PARTITION BY plan ORDER BY monthly_fee, id) AS monthly_fee_bucket FROM subscriptions WINDOW w_recent AS (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, plan, start_date, end_date, running_monthly_fee, customer_id_stddev_samp_monthly_fee, monthly_fee_avg_5_prior FROM metrics
